<?php
if(!defined('ABSPATH'))exit;
final class GRID_Cookie_Admin {
    public static function boot(){add_action('admin_notices',array(__CLASS__,'dependency_notice'));add_action('admin_post_grid_cookie_import_ids',array(__CLASS__,'import_ids'));add_action('admin_enqueue_scripts',array(__CLASS__,'assets'));add_action('admin_menu',array(__CLASS__,'menu'),50);add_action('admin_menu',array(__CLASS__,'group_grid_menus'),PHP_INT_MAX);add_action('admin_post_grid_cookie_policy',array(__CLASS__,'create_policy'));add_action('admin_post_grid_cookie_export',array(__CLASS__,'export'));add_filter('plugin_action_links_'.plugin_basename(GRID_Cookie_Consent::FILE),array(__CLASS__,'links'));}
    public static function dependencies(){
        if(!function_exists('get_plugins'))require_once ABSPATH.'wp-admin/includes/plugin.php';$plugins=get_plugins();$result=array();
        foreach(array('google-site-kit'=>array('Site Kit by Google','google-site-kit/google-site-kit.php'),'microsoft-clarity'=>array('Microsoft Clarity','microsoft-clarity/clarity.php'))as$slug=>$item){$file=$item[1];$installed=isset($plugins[$file]);$active=$installed&&is_plugin_active($file);$url='';$action='';if(!$installed&&current_user_can('install_plugins')){$action='Install';$url=wp_nonce_url(admin_url('update.php?action=install-plugin&plugin='.$slug),'install-plugin_'.$slug);}elseif($installed&&!$active&&current_user_can('activate_plugin',$file)){$action='Activate';$url=wp_nonce_url(admin_url('plugins.php?action=activate&plugin='.rawurlencode($file)),'activate-plugin_'.$file);}$result[]=array('name'=>$item[0],'installed'=>$installed,'active'=>$active,'url'=>$url,'action'=>$action);}
        return$result;
    }
    public static function dependency_notice(){if(!current_user_can('manage_options'))return;$screen=get_current_screen();if(!$screen||!in_array($screen->id,array('plugins','toplevel_page_grid-tools','grid-tools_page_grid-cookie-consent'),true))return;foreach(self::dependencies()as$d)if(!$d['active']){echo'<div class="notice notice-warning"><p>GRID Cookie Consent: complete the Google/Microsoft integration setup in <a href="'.esc_url(admin_url('admin.php?page=grid-cookie-consent')).'">Cookie consent settings</a>. Missing integrations do not disable the consent banner or existing protections.</p></div>';break;}}
    public static function dependency_panel(){echo'<h2>Official integration plugins</h2><p>The GRID plugin checks these integrations and provides installation/activation actions. Connect the relevant accounts in each official plugin. Existing connected IDs can be imported without replacing IDs already saved here. GRID owns public tag loading to prevent duplicates; it does not change the other plugins’ settings. Clarity session recording remains consent-based.</p><ul>';foreach(self::dependencies()as$d){echo'<li><strong>'.esc_html($d['name']).'</strong>: '.($d['active']?'Active':($d['installed']?'Installed, inactive':'Not installed'));if($d['url'])echo' — <a class="button" href="'.esc_url($d['url']).'">'.esc_html($d['action'].' '.$d['name']).'</a>';echo'</li>';}echo'</ul><form action="'.esc_url(admin_url('admin-post.php')).'" method="post"><input type="hidden" name="action" value="grid_cookie_import_ids">';wp_nonce_field('grid_cookie_import_ids');submit_button('Import connected IDs (keep existing values)','secondary','submit',false);echo'</form>';}
    public static function import_ids(){if(!current_user_can('manage_options'))wp_die('Not permitted',403);check_admin_referer('grid_cookie_import_ids');GRID_Cookie_Settings::import_connected();wp_safe_redirect(admin_url('admin.php?page=grid-cookie-consent'));exit;}
    public static function links($links){array_unshift($links,'<a href="'.esc_url(admin_url('admin.php?page=grid-cookie-consent')).'">Settings</a>');return$links;}
    public static function menu(){add_menu_page('GRID Tools','GRID Tools','manage_options','grid-tools',array(__CLASS__,'overview'),plugins_url('assets/branding/grid-flower.svg',GRID_Cookie_Consent::FILE),81);add_submenu_page('grid-tools','GRID Tools','Overview','manage_options','grid-tools',array(__CLASS__,'overview'));add_submenu_page('grid-tools','Cookie consent','Cookie consent','manage_options','grid-cookie-consent',array(__CLASS__,'page'));add_submenu_page('grid-tools','Consent records','Consent records','manage_options','grid-cookie-records',array(__CLASS__,'records'));}
    public static function group_grid_menus(){
        if(!GRID_Cookie_Settings::get()['group_menu'])return;global$submenu,$menu; $allowed=array('grid-arendal','grid-a11y','grid-editorial-tools','grid-modules','grid-labels','grid-fields');$moves=array();
        foreach(array('grid-arendal','grid-editorial-tools')as$parent){
            if(empty($submenu[$parent]))continue;$entries=$submenu[$parent];$safe=true;$batch=array();
            foreach($entries as$entry){$slug=$entry[2]??'';if(!in_array($slug,$allowed,true)){$safe=false;break;}$old=get_plugin_page_hookname($slug,$parent);if(!$old||has_action($old)===false){$safe=false;break;}$batch[]=array('entry'=>$entry,'old'=>$old);}
            // Unknown third-party children keep their original parent. Never strand pages.
            if(!$safe)continue;foreach($batch as$x)$moves[]=$x;remove_menu_page($parent);unset($submenu[$parent]);
        }
        foreach($moves as$x){$entry=$x['entry'];$old=$x['old'];$slug=$entry[2];$label=$entry[0];if($slug==='grid-arendal')$label='Accessibility overview';if($slug==='grid-editorial-tools')$label='Editorial tools';$predicted=get_plugin_page_hookname($slug,'grid-tools');$delegate=$predicted===$old?'':function()use($old){do_action($old);};$new=add_submenu_page('grid-tools',$entry[3]??strip_tags($label),$label,$entry[1],$slug,$delegate);if($new&&$new!==$old){foreach(array('load-','admin_head-','admin_footer-')as$prefix)add_action($prefix.$new,function()use($prefix,$old){do_action($prefix.$old);});}}
    }
    public static function assets(){wp_enqueue_style('grid-cookie-admin',plugins_url('assets/admin.css',GRID_Cookie_Consent::FILE),array(),GRID_Cookie_Consent::VERSION);}
    public static function overview(){
        if(!current_user_can('manage_options'))return;
        echo '<div class="wrap gcc-admin"><header class="gcc-brand-header"><img src="'.esc_url(plugins_url('assets/branding/grid-flower.svg',GRID_Cookie_Consent::FILE)).'" width="48" height="48" alt=""><div><h1>GRID Tools</h1><p>Website tools, brought to you by <a href="https://www.grida.no/">GRID-Arendal</a></p></div></header><div class="gcc-tool-cards">';
        $cards=array(array('Cookie consent','Privacy choices, local consent records and configurable policies for this website.','grid-cookie-consent','Consent settings'));
        if(class_exists('GRID_Accessibility_Toolbar',false))$cards[]=array('Accessibility Widget','Visitor reading preferences, accessibility profiles and optional website translation.','grid-a11y','Widget settings');
        if(class_exists('GRID_Arendal_Core',false))$cards[]=array('Editorial Tools','Content workspace, editable field groups and the editorial modules selected for this website.','grid-modules','Editorial settings');
        foreach($cards as$card)echo '<section class="gcc-tool-card"><h2>'.esc_html($card[0]).'</h2><p>'.esc_html($card[1]).'</p><a class="button button-primary" href="'.esc_url(admin_url('admin.php?page='.$card[2])).'">'.esc_html($card[3]).'</a></section>';
        echo '</div><p class="gcc-brand-note">Independent plugins, one convenient menu. Each retains its own settings, data, permissions and WordPress updates. Deactivating Cookie Consent or turning off menu grouping restores the original menus. Unknown menu extensions keep their original parents.</p></div>';
    }
    public static function input($key,$label,$type='text',$help=''){$s=GRID_Cookie_Settings::get();echo'<tr><th scope="row"><label for="gcc-'.$key.'">'.esc_html($label).'</label></th><td><input id="gcc-'.$key.'" name="grid_cookie_consent['.$key.']" type="'.esc_attr($type).'" value="'.esc_attr($s[$key]).'" class="regular-text">';if($help)echo'<p class="description">'.esc_html($help).'</p>';echo'</td></tr>';}
    public static function page(){
        if(!current_user_can('manage_options'))return;$s=GRID_Cookie_Settings::get();echo'<div class="wrap"><h1>Cookie consent</h1><p>No geo-IP service. Consent-controlled services wait for a saved choice. Google Analytics can optionally use advanced Consent Mode, which sends cookieless measurements before consent and after rejection. This supports compliance, but the site owner must review all tracking, notices, contracts and international transfers.</p>';settings_errors('grid_cookie');self::dependency_panel();
        if(!$s['reviewed'])echo'<div class="notice notice-warning inline"><p><strong>Setup not reviewed:</strong> known legacy trackers are blocked, and optional services cannot be enabled until the notice and inventory are reviewed.</p></div>';
        echo'<form action="options.php" method="post">';settings_fields('grid_cookie');echo'<h2>1. Controller and policy</h2><p>Link an existing approved policy below, or use Create policy draft after saving your settings. Nothing is published automatically.</p><table class="form-table">';self::input('controller','Controller / organisation');self::input('contact','Privacy contact','text','Email address or contact details for privacy questions. Do not use a placeholder in a published policy.');self::input('privacy','Cookie / privacy policy URL','url','Choose a published page below, or use a valid policy URL maintained elsewhere.');echo'<tr><th>Existing policy page</th><td>';wp_dropdown_pages(array('name'=>'grid_cookie_consent[privacy_page]','selected'=>url_to_postid($s['privacy']),'show_option_none'=>'Use URL above / choose a published page','option_none_value'=>0,'post_status'=>'publish'));echo'</td></tr></table><h2>2. Managed services</h2><p>This plugin owns these loaders. Existing Google Analytics, GTM, Clarity and recognised advertising bootstrap snippets are suppressed to avoid duplicate/unconsented requests. GTM and Google advertising are not automatically enabled. Exclude sensitive pages in the vendor configuration.</p><table class="form-table">';self::input('ga','GA4 measurement ID','text','For example G-XXXXXXXXXX. Google signals and ad personalisation stay off.');echo'<tr><th>Google Consent Mode</th><td><select name="grid_cookie_consent[ga_mode]"><option value="basic" '.selected($s['ga_mode'],'basic',false).'>Basic — Google blocked until analytics consent</option><option value="advanced" '.selected($s['ga_mode'],'advanced',false).'>Advanced — cookieless Google measurement before consent and after rejection</option></select><p class="description">Advanced mode sends requests to Google even when consent is declined. It does not make processing automatically lawful. Review the lawful basis, disclosures and transfers. Analytics cookies still require consent; GPC blocks Google entirely. Other statistics services and Clarity remain opt-in.</p></td></tr>';self::input('clarity','Clarity project ID','text','Session recording is a separate purpose. Text is masked; ad storage stays denied. Clarity is not suitable for websites targeting under-18s.');echo'</table>';
        echo'<h2>3. Behaviour and retention</h2>';foreach(array('group_menu'=>'Group recognised GRID plugin settings under one GRID Tools menu (UI only; turn off to restore original menus)','enabled'=>'Enable consent controls and known-tracker blocking','functional'=>'Gate external frames, GTranslate and Google Fonts behind the External content choice','logged_in'=>'Allow configured statistics/recording for signed-in users','reviewed'=>'I have reviewed this site’s policy, providers, purposes, contracts/transfer safeguards, and tested every tracking integration')as$k=>$text)echo'<p><label><input type="checkbox" name="grid_cookie_consent['.$k.']" value="1" '.checked($s[$k],1,false).'> '.esc_html($text).'</label></p>';echo'<table class="form-table">';self::input('days','Remember choices (1–180 days)','number');self::input('retention','Local consent records (up to 365 days)','number','At least the consent-choice duration. Retention is a site policy choice, not a universal legal rule.');echo'</table>';
        echo'<h2>4. Appearance and language</h2><table class="form-table">';foreach(array('accent'=>'Button colour (white text)','background'=>'Panel background','text'=>'Panel text')as$k=>$l)self::input($k,$l,'color');self::input('radius','Corner radius (0–24)','number');self::input('language','Language code or auto','text','English (en) and Norwegian Bokmål (nb) are built in. Additional translations can be supplied below.');echo'<tr><th>Banner position</th><td><select name="grid_cookie_consent[position]">';foreach(array('bottom-left'=>'Floating box — bottom left','bottom-right'=>'Floating box — bottom right','bottom-bar'=>'Full-width banner — bottom')as$p=>$label)echo'<option value="'.esc_attr($p).'" '.selected($s['position'],$p,false).'>'.esc_html($label).'</option>';echo'</select></td></tr><tr><th>Font</th><td><select name="grid_cookie_consent[font]"><option value="system" '.selected($s['font'],'system',false).'>System font — no font downloads</option><option value="inherit" '.selected($s['font'],'inherit',false).'>Inherit website font</option></select></td></tr></table>';
        echo'<details><summary><strong>Advanced service registry and translations</strong></summary><p>Custom scripts require unfiltered_html permission, HTTPS, an explicit provider, purpose, category and storage list. Audit their downstream requests. Unrecognised dynamic scripts, CSS pixels, server-side tracking and arbitrary vendor containers are not automatically made safe.</p><p>Service JSON example: <code>[{"id":"example","name":"Example","provider":"Example Ltd","purpose":"Visitor statistics","category":"analytics","src":"https://example.org/script.js","cookies":["example_*"]}]</code></p><label for="gcc-services">Services (JSON)</label><textarea id="gcc-services" name="grid_cookie_consent[services]" rows="8" class="large-text code">'.esc_textarea(wp_json_encode($s['services'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</textarea><p>Translations: language-code objects with known label keys. Missing keys fall back to English. No third-party translation request is made by this consent UI.</p><label for="gcc-translations">Translations (JSON)</label><textarea id="gcc-translations" name="grid_cookie_consent[translations]" rows="6" class="large-text code">'.esc_textarea(wp_json_encode($s['translations'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</textarea></details>';submit_button('Save consent settings');echo'</form>';
        echo'<h2>Policy setup</h2><form action="'.esc_url(admin_url('admin-post.php')).'" method="post"><input type="hidden" name="action" value="grid_cookie_policy">';wp_nonce_field('grid_cookie_policy');submit_button('Create editable policy draft','secondary');echo'</form><p>The draft is a starting point based on configured services. It includes no blanket claim of GDPR/global compliance. Add hosting logs, forms, accounts, international transfers and other site-specific processing. Review and publish it in WordPress, then link its public URL above.</p><h2>Integration checks</h2><p>Use a clean browser and inspect requests before consent, after rejection, each purpose, withdrawal, expiry and GPC. Clear all page/hosting/CDN caches after changes. Exclude grid-cookie-config, grid-cookie-defaults and grid-cookie-runtime from delayed-JS and HTML rewriting optimisers. Consent is evaluated per visitor in the browser, so cached public HTML stays inert.</p><p>Add <code>[grid_cookie_settings]</code> to your footer or policy for an additional preferences link. <code>[grid_cookie_policy]</code> renders the current declaration. This plugin has no separate update-settings page; use WordPress Plugins/Updates.</p><h2>Preview (no storage or network trackers)</h2><div id="grid-cookie-consent" data-ga-a11y-ignore data-clarity-mask="true"></div>';
        echo'<script id="grid-cookie-config" type="application/json">'.wp_json_encode(GRID_Cookie_Consent::config(true),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script>';wp_enqueue_style('grid-cookie-preview',plugins_url('assets/consent.css',GRID_Cookie_Consent::FILE),array(),GRID_Cookie_Consent::VERSION);wp_enqueue_script('grid-cookie-preview',plugins_url('assets/consent.js',GRID_Cookie_Consent::FILE),array(),GRID_Cookie_Consent::VERSION,true);echo'</div>';
    }
    public static function create_policy(){if(!current_user_can('manage_options')||!current_user_can('edit_pages'))wp_die('Not permitted',403);check_admin_referer('grid_cookie_policy');$id=(int)get_option('grid_cookie_policy_draft',0);if(!$id||!get_post($id)){$id=wp_insert_post(array('post_type'=>'page','post_status'=>'draft','post_title'=>'Cookies and privacy choices','post_content'=>'<p><strong>Draft for site-owner review.</strong> Complete controller/contact, service inventory, hosting logs and vendor transfer safeguards before publishing. This notice is not legal certification.</p>'.GRID_Cookie_Settings::policy(true)),true);if(is_wp_error($id))wp_die('Could not create draft');update_option('grid_cookie_policy_draft',$id,false);}wp_safe_redirect(get_edit_post_link($id,'raw'));exit;}
    public static function records(){if(!current_user_can('manage_options'))return;global$wpdb;$t=GRID_Cookie_Receipts::table();$rows=$wpdb->get_results("SELECT id,policy,created,choices,method,language,gpc FROM $t ORDER BY created DESC LIMIT 100",ARRAY_A);echo'<div class="wrap"><h1>Consent records</h1><p>Latest 100 local decision receipts. No IP address, user agent, account ID or page URL is recorded here. These are controller-held records, not identity verification or proof that every site integration obeyed the choice.</p><p><a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=grid_cookie_export'),'grid_cookie_export')).'">Export latest 10,000 receipts and notice snapshots (JSON)</a></p><table class="widefat striped"><thead><tr><th>Receipt ID</th><th>UTC</th><th>Action / language</th><th>Choices</th><th>Policy revision</th></tr></thead><tbody>';foreach($rows as$r)echo'<tr><td><code>'.esc_html($r['id']).'</code></td><td>'.esc_html(gmdate('Y-m-d H:i:s',(int)$r['created'])).'</td><td>'.esc_html($r['method'].' / '.$r['language'].($r['gpc']?' / GPC':'')).'</td><td><code>'.esc_html($r['choices']).'</code></td><td>'.esc_html($r['policy']).'</td></tr>';echo'</tbody></table></div>';}
    public static function export(){if(!current_user_can('manage_options'))wp_die('Not permitted',403);check_admin_referer('grid_cookie_export');global$wpdb;$t=GRID_Cookie_Receipts::table();$p=GRID_Cookie_Receipts::policies();$rows=$wpdb->get_results("SELECT * FROM $t ORDER BY created DESC LIMIT 10000",ARRAY_A);$snapshots=$wpdb->get_results("SELECT * FROM $p",ARRAY_A);nocache_headers();header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="consent-records.json"');header('X-Content-Type-Options: nosniff');echo wp_json_encode(array('exported_utc'=>gmdate('c'),'limit'=>10000,'receipts'=>$rows,'policies'=>$snapshots),JSON_PRETTY_PRINT);exit;}
}
